{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 지정 금연구역의 경계 표시 방법과 안내판 기재 내용",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 금연구역을 지정한 경우 시민이 잘 알 수 있는 장소에 금연구역 안내표지판을 설치해야 하며, 이때 금연구역의 경계를 명확히 구분하여 표시해야 한다.",
          "b_ids": "금연:제7조제1항"
        },
        {
          "a_text": "안내표지판에는 금연구역 조성목적과 간접흡연 피해방지를 위한 문구를 표시해야 한다.",
          "b_ids": "금연:제7조제2항"
        },
        {
          "a_text": "안내표지판의 모양, 크기와 설치방법, 경계의 표시방법 등 필요한 사항은 규칙으로 정한다.",
          "b_ids": "금연:제7조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
